"""Generated byte streams only; installed pydicom is a parser comparator."""
import copy
import hashlib
import io
import json
from pathlib import Path
import struct
import subprocess
import sys
import zipfile
import pytest
import pydicom
from epi_next import a2_diagnostic_v2 as v2
from test_a2_six_sop import dicom, fixture

class Stream:
    def __init__(self, data):
        self.data=data; self.emitted=0; self.hash=hashlib.sha256()
    def read(self,n):
        if self.emitted+n>len(self.data): raise v2.old.HeaderError('SHORT')
        raw=self.data[self.emitted:self.emitted+n];self.emitted+=n;self.hash.update(raw);return raw
    def skip(self,n): self.read(n)

def raw_dataset(i=1):
    raw=dicom(i)[0]
    ds=pydicom.dcmread(io.BytesIO(raw));ds.SliceThickness='';ds.SpecificCharacterSet='ISO_IR 6'
    b=io.BytesIO();pydicom.dcmwrite(b,ds,enforce_file_format=True);return b.getvalue()

def fields():
    r=fixture_request_fields()
    return {tuple(int(x,16) for x in f['tag'].split(',')):f['keyword'] for f in r}

def fixture_request_fields():
    from test_a1_prepare import generated_request
    return [f for f in generated_request()['requests'][0]['field_value_whitelist'] if f['keyword'] in v2.RULES]

def elem(tag,vr,raw):
    head=struct.pack('<HH',*tag)+vr.encode()
    return head+(b'\0\0'+struct.pack('<I',len(raw)) if vr in v2.old.LONG_VR else struct.pack('<H',len(raw)))+raw

def change(raw,tag,vr,value):
    # pydicom used only on generated bytes; preserves Part10 structural bounds.
    ds=pydicom.dcmread(io.BytesIO(raw));ds.add_new(tag,vr,value)
    b=io.BytesIO();pydicom.dcmwrite(b,ds,enforce_file_format=True);return b.getvalue()

def ctx():return v2.context('GENERATED-1','dataset',(8,24),'SOPInstanceUID','UI',0,302,310)

@pytest.mark.parametrize('kind,present,raw,condition,reason',[
 ('1',True,b'',None,'TYPE1_EMPTY'),('1',False,b'',None,'REQUIRED_FIELD_ABSENT'),
 ('1C',True,b'',True,'TYPE1_EMPTY'),('1C',False,b'',True,'REQUIRED_FIELD_ABSENT'),
 ('1C',True,b'',None,'CONDITION_UNKNOWN'),('2',False,b'',None,'REQUIRED_FIELD_ABSENT'),
 ('2C',False,b'',True,'REQUIRED_FIELD_ABSENT')])
def test_required_types(kind,present,raw,condition,reason):
    with pytest.raises(v2.DiagnosticError) as e:v2.uid_value(raw,present,kind,condition,ctx(),'GENERATED_RULE')
    assert e.value.diagnostic['reason_code']==reason

@pytest.mark.parametrize('kind,present,condition',[('2',True,None),('3',True,None),('3',False,None),('1C',False,False),('2C',True,True)])
def test_permitted_empty_or_absent(kind,present,condition):
    assert v2.uid_value(b'',present,kind,condition,ctx(),'GENERATED_ONLY') is None

@pytest.mark.parametrize('raw,reason',[(b'1.'+b'2'*64,'UID_LENGTH_EXCEEDS_64'),(b'1.02','UID_SYNTAX_INVALID'),(b'1.2 ','UID_SYNTAX_INVALID'),(b'1.2\0\0','UID_INVALID_PADDING'),(b'1.\xff','UID_SYNTAX_INVALID')])
def test_nonempty_uid_rules(raw,reason):
    with pytest.raises(v2.DiagnosticError) as e:v2.uid_value(raw,True,'3',None,ctx(),'GENERATED_ONLY')
    assert e.value.diagnostic['reason_code']==reason
    assert 'raw' not in e.value.diagnostic

def test_generated_valid_native_header_and_no_uid_trace():
    raw=raw_dataset();s=Stream(raw);h=v2.parse(s,'GENERATED-1',fields())
    ds=pydicom.dcmread(io.BytesIO(raw),stop_before_pixels=True)
    assert h['values']['SOPInstanceUID']==ds.SOPInstanceUID
    assert h['values']['SliceThickness'] is None
    assert h['geometry']['rows']==ds.Rows
    assert '1.2.3.1' not in json.dumps(h['diagnostics'])
    assert raw[s.emitted:s.emitted+4]==b'\xfe\xff\0\xe0'  # untouched PixelData item

def test_empty_sop_and_missing_meta_are_both_diagnosed():
    raw=change(raw_dataset(),(8,24),'UI','')
    ds=pydicom.dcmread(io.BytesIO(raw));del ds.file_meta.MediaStorageSOPInstanceUID
    b=io.BytesIO();pydicom.dcmwrite(b,ds,enforce_file_format=False)
    with pytest.raises(v2.DiagnosticError) as e:v2.parse(Stream(b.getvalue()),'GENERATED-1',fields())
    failures=e.value.diagnostic['validation_failures']
    assert any(f['domain']=='meta' and f['keyword']=='MediaStorageSOPInstanceUID' for f in failures)
    f=next(f for f in failures if f['tag']=='0008,0018')
    assert f['reason_code']=='TYPE1_EMPTY' and f['declared_VL']==0 and f['VR']=='UI'
    assert f['consumed_prefix_bytes']-f['element_offset']==8
    # pydicom parses an empty UI; this demonstrates parser != compliance.
    assert pydicom.dcmread(io.BytesIO(b.getvalue())).SOPInstanceUID==''

def test_unknown_condition_does_not_admit():
    raw=raw_dataset();ds=pydicom.dcmread(io.BytesIO(raw));del ds.RescaleType
    b=io.BytesIO();pydicom.dcmwrite(b,ds,enforce_file_format=True)
    with pytest.raises(v2.DiagnosticError) as e:v2.parse(Stream(b.getvalue()),'GENERATED-1',fields())
    assert any(f['keyword']=='RescaleType' and f['reason_code']=='CONDITION_UNKNOWN' for f in e.value.diagnostic['validation_failures'])

@pytest.mark.parametrize('suffix,reason',[
 (elem((8,0x1110),'SQ',b''),'CONTAINER_NOT_SUPPORTED_NO_VALUE_READ'),
 (struct.pack('<HH',8,24)+b'UI'+struct.pack('<H',1)+b'1','ODD_VALUE_LENGTH'),
 (struct.pack('<HH',8,24)+b'UI'+struct.pack('<H',64)+b'1','HEADER_READ_TRUNCATED')])
def test_structure_boundaries_and_sequence(suffix,reason):
    raw=raw_dataset();meta_end=144+struct.unpack_from('<I',raw,140)[0]
    s=Stream(raw[:meta_end]+suffix)
    with pytest.raises(v2.DiagnosticError) as e:v2.parse(s,'GENERATED-1',fields())
    d=e.value.diagnostic;assert d['reason_code']==reason
    if d['VR']=='SQ':
        assert d['domain']=='dataset/sequence' and d['sequence_path']==['0008,1110']
        assert s.emitted==meta_end+12


def test_context_sensitive_rule_not_root_type_in_sequence():
    c=v2.context('GENERATED-1','dataset/sequence',(8,0x1155),'ReferencedSOPInstanceUID','UI',0,10,18,('0008,1140','item:0'))
    with pytest.raises(v2.DiagnosticError) as e:v2.uid_value(b'',True,'1',None,c,'PS3.3-IMAGE-SOP-INSTANCE-REFERENCE-MACRO')
    assert e.value.diagnostic['sequence_path']==['0008,1140','item:0']


def request(tmp_path,missing=False):
    r=fixture(tmp_path);archive=Path(r['source_archive']['path'])
    with zipfile.ZipFile(archive,'w',zipfile.ZIP_DEFLATED) as z:
        for i in range(1,7):z.writestr(f'GENERATED/{i}.dcm',change(raw_dataset(i),(8,24),'UI','') if missing else raw_dataset(i))
    with zipfile.ZipFile(archive) as z:
        for selected,m in zip(r['selection'],z.infolist()):
            selected['member'].update(compressed_bytes=m.compress_size,uncompressed_bytes=m.file_size,crc32=m.CRC,header_offset=m.header_offset)
    Path(r['inventory_binding']['path']).write_text(json.dumps([s['member'] for s in r['selection']]))
    r['inventory_binding']['sha256']=v2.old.sha(r['inventory_binding']['path'])
    st=archive.stat();r['source_archive'].update(bytes=st.st_size,stat_binding={'device':st.st_dev,'inode':st.st_ino,'mtime_ns':st.st_mtime_ns})
    return r


def test_generated_same_pipeline_decode_and_sanitized_artifacts(tmp_path,monkeypatch):
    r=request(tmp_path);monkeypatch.setitem(v2.OVERALL,'disk_free_floor_bytes',0)
    out=tmp_path/'out';receipt=v2.pipeline(r,out,True)
    assert receipt['status']=='COMPLETE_TECHNICAL_SUBSET',receipt
    assert receipt['decoded_SOP_count']==6
    for p in out.rglob('*.json'):
        text=p.read_text();assert '1.2.3.' not in text and 'GENERATED_FORBIDDEN' not in text
    assert len(list(out.rglob('*.png')))==6


def test_generated_quarantine_no_decode(tmp_path,monkeypatch):
    r=request(tmp_path,True);monkeypatch.setitem(v2.OVERALL,'disk_free_floor_bytes',0)
    out=tmp_path/'out';receipt=v2.pipeline(r,out,True)
    assert receipt['status']=='NO_ELIGIBLE_SOP' and receipt['decoded_SOP_count']==0
    assert not list(out.rglob('*.npy'))


def test_dictionary_comparator_not_type_authority():
    from pydicom.datadict import dictionary_VR,dictionary_keyword
    for tag,key in fields().items():
        assert dictionary_keyword(tag)==key
        assert v2.old.FIELD_VR[key] in dictionary_VR(tag)

@pytest.mark.parametrize('raw',[b'1.2\0',b'1.23',b'0.2\0'])
def test_valid_uid_padding(raw):
    assert v2.uid_value(raw,True,'1',None,ctx(),'PS3.5-9.1')==raw.rstrip(b'\0').decode()

def test_absent_type2_in_actual_profile_rejected():
    ds=pydicom.dcmread(io.BytesIO(raw_dataset()));del ds.SliceThickness
    b=io.BytesIO();pydicom.dcmwrite(b,ds,enforce_file_format=True)
    with pytest.raises(v2.DiagnosticError) as e:v2.parse(Stream(b.getvalue()),'GENERATED-1',fields())
    assert any(f['keyword']=='SliceThickness' and f['reason_code']=='REQUIRED_FIELD_ABSENT' for f in e.value.diagnostic['validation_failures'])

def test_budget_and_vr_diagnostics_hide_values():
    raw=raw_dataset();meta_end=144+struct.unpack_from('<I',raw,140)[0]
    for suffix,reason in [(elem((8,24),'UI',b'X'*4098),'WHITELIST_VALUE_LIMIT'),(elem((8,24),'CS',b'SECRET_GENERATED'),'WHITELIST_VR_MISMATCH')]:
        with pytest.raises(v2.DiagnosticError) as e:v2.parse(Stream(raw[:meta_end]+suffix),'GENERATED-1',fields())
        assert e.value.diagnostic['reason_code']==reason
        assert 'SECRET_GENERATED' not in str(e.value) and 'SECRET_GENERATED' not in json.dumps(e.value.diagnostic)

def test_meta_boundary_stops_before_dataset_value():
    raw=bytearray(raw_dataset());struct.pack_into('<I',raw,140,10)
    with pytest.raises(v2.DiagnosticError) as e:v2.parse(Stream(bytes(raw)),'GENERATED-1',fields())
    assert e.value.diagnostic['domain']=='meta'
    assert e.value.diagnostic['reason_code']=='ELEMENT_EXCEEDS_CONTEXT_BOUNDARY'

def test_failed_decode_has_no_published_artifacts(tmp_path,monkeypatch):
    r=request(tmp_path);monkeypatch.setitem(v2.OVERALL,'disk_free_floor_bytes',0)
    def fail(*args):raise ValueError('GENERATED_PRIVATE_UID_1.2.3.4')
    monkeypatch.setattr(v2.v1,'decode_pixels',fail)
    out=tmp_path/'out';receipt=v2.pipeline(r,out,True)
    assert receipt['status']=='FAILED' and 'GENERATED_PRIVATE_UID' not in json.dumps(receipt)
    assert not list(out.rglob('*.npy'))

def test_exact_scope_validation_rejects_caps_or_models(tmp_path,monkeypatch):
    r=request(tmp_path);parent=copy.deepcopy(r)
    monkeypatch.setattr(v2,'bound_json',lambda *a:parent)
    r.update(parent_request_path='GENERATED_ONLY',schema='A2_DIAGNOSTIC_V2',diagnosis_caps=v2.A,decode_caps=v2.B,overall_caps=v2.OVERALL,rules={k:list(v) for k,v in v2.RULES.items()},models_permitted=False,new_codecs_permitted=False)
    v2.validate(r)
    r['models_permitted']=True
    with pytest.raises(v2.old.GuardError):v2.validate(r)

@pytest.mark.parametrize('code',['WALL_LIMIT','RSS_LIMIT','COMPRESSED_LIMIT','INFLATED_LIMIT'])
def test_resource_guard_keeps_safe_code(code):
    class Stop(Stream):
        def read(self,n):raise v2.old.GuardError(code)
    with pytest.raises(v2.DiagnosticError) as e:v2.parse(Stop(b''),'GENERATED-1',fields())
    assert e.value.diagnostic['reason_code']==code
    assert e.value.diagnostic['failure_class']=='resource_stop'

def test_resource_stop_preserved_no_next_member_no_decode(tmp_path,monkeypatch):
    r=request(tmp_path);monkeypatch.setitem(v2.OVERALL,'disk_free_floor_bytes',0)
    def resource_stop(stream,member,allowed):
        v2.reject(dict(v2.context(member,'dataset',consumed=stream.emitted),failure_class='resource_stop'),'RSS_LIMIT','BOUNDED_STRUCTURE_V2')
    monkeypatch.setattr(v2,'parse',resource_stop)
    out=tmp_path/'out';receipt=v2.pipeline(r,out,True)
    assert receipt['status']=='DIAGNOSIS_RESOURCE_STOP' and receipt['decoded_SOP_count']==0
    d=json.loads((out/'diagnostics.json').read_text())
    assert len(d['rows'])==1 and d['rows'][0]['diagnostic']['reason_code']=='RSS_LIMIT'

def test_known_decode_stop_code_survives_phase(tmp_path,monkeypatch):
    r=request(tmp_path);monkeypatch.setitem(v2.OVERALL,'disk_free_floor_bytes',0)
    def fail(*args):raise v2.old.GuardError('NATIVE_OUTPUT_LIMIT')
    monkeypatch.setattr(v2.v1,'decode_pixels',fail)
    receipt=v2.pipeline(r,tmp_path/'out',True)
    assert receipt['reason_code']=='NATIVE_OUTPUT_LIMIT' and receipt['status']=='FAILED'
